/* =========================================================
   RAMIS — PREMIUM DIGITAL STORE HERO
   Root: 63b6560
   ========================================================= */

/* =========================================================
   01. MAIN HERO
   ========================================================= */

selector {
    --ramis-primary: #006660;
    --ramis-dark: #003F3C;
    --ramis-secondary: #004F4B;
    --ramis-gold: #FFCE3A;

    position: relative;
    overflow: hidden;

    background:
        radial-gradient(
            circle at 88% 15%,
            rgba(255, 206, 58, 0.12),
            transparent 29%
        ),
        radial-gradient(
            circle at 8% 85%,
            rgba(0, 180, 165, 0.17),
            transparent 34%
        ),
        linear-gradient(
            135deg,
            #003F3C 0%,
            #006660 52%,
            #00332F 100%
        );

    border-radius: 0 0 30px 30px;

    isolation: isolate;
}


/* =========================================================
   02. ATMOSPHERIC LIGHT EFFECTS
   ========================================================= */

selector::before {
    content: "";
    position: absolute;

    width: 420px;
    height: 420px;

    top: -220px;
    right: -120px;

    background: rgba(255, 206, 58, 0.09);

    border-radius: 50%;

    filter: blur(80px);

    pointer-events: none;
    z-index: -1;
}

selector::after {
    content: "";
    position: absolute;

    width: 360px;
    height: 360px;

    bottom: -220px;
    left: -120px;

    background: rgba(0, 190, 175, 0.10);

    border-radius: 50%;

    filter: blur(85px);

    pointer-events: none;
    z-index: -1;
}


/* =========================================================
   03. TEXT CONTAINER
   ========================================================= */

selector .elementor-element-ffed1b2 {
    position: relative;
    z-index: 2;
}


/* =========================================================
   04. HERO TITLE
   ========================================================= */

selector .elementor-element-993c01d {
    position: relative;
}

selector .elementor-element-993c01d p {
    margin: 0;

    color: #FFFFFF !important;

    font-size: clamp(32px, 4vw, 46px);
    font-weight: 900;
    line-height: 1.4;

    letter-spacing: -0.5px;

    text-shadow:
        0 4px 20px rgba(0, 0, 0, 0.18);
}


/* =========================================================
   05. GOLD DECORATIVE LINE
   ========================================================= */

selector .elementor-element-993c01d::after {
    content: "";

    display: block;

    width: 55px;
    height: 4px;

    margin-top: 14px;

    background: var(--ramis-gold);

    border-radius: 20px;

    box-shadow:
        0 0 14px rgba(255, 206, 58, 0.22);

    transition:
        width .4s cubic-bezier(.2,.8,.2,1),
        box-shadow .4s ease;
}

selector .elementor-element-993c01d:hover::after {
    width: 82px;

    box-shadow:
        0 0 20px rgba(255, 206, 58, 0.35);
}


/* =========================================================
   06. HERO DESCRIPTION
   ========================================================= */

selector .elementor-element-e48adae {
    position: relative;
    z-index: 2;
}

selector .elementor-element-e48adae p {
    margin: 0;

    max-width: 520px;

    color: rgba(255, 255, 255, 0.76) !important;

    font-size: 15px;
    font-weight: 400;

    line-height: 2.15;

    transition:
        color .35s ease;
}

selector .elementor-element-e48adae:hover p {
    color: rgba(255, 255, 255, 0.90) !important;
}


/* =========================================================
   07. IMAGE CONTAINER
   ========================================================= */

selector .elementor-element-5cfbc7a {
    position: relative;
    z-index: 2;

    transition:
        transform .4s cubic-bezier(.2,.8,.2,1);
}


/* =========================================================
   08. PREMIUM IMAGE FRAME
   ========================================================= */

selector .elementor-element-5cfbc7a::before {
    content: "";

    position: absolute;

    inset: -7px;

    border: 1px solid rgba(255, 206, 58, 0.28);

    border-radius: 25px;

    pointer-events: none;

    opacity: .8;

    transition:
        border-color .4s ease,
        opacity .4s ease;
}


/* =========================================================
   09. IMAGE
   ========================================================= */

selector .elementor-element-fcd108f img {
    display: block;

    width: 100%;
    height: auto;

    border-radius: 20px;

    border: 1px solid rgba(255, 255, 255, 0.15);

    box-shadow:
        0 25px 55px rgba(0, 0, 0, 0.28);

    transform: rotate(2deg);

    transition:
        transform .5s cubic-bezier(.2,.8,.2,1),
        box-shadow .5s ease,
        border-color .5s ease;
}


/* =========================================================
   10. IMAGE HOVER
   ========================================================= */

selector .elementor-element-5cfbc7a:hover img {
    transform:
        rotate(0deg)
        translateY(-7px);

    box-shadow:
        0 32px 65px rgba(0, 0, 0, 0.34);

    border-color:
        rgba(255, 206, 58, 0.30);
}

selector .elementor-element-5cfbc7a:hover::before {
    border-color:
        rgba(255, 206, 58, 0.48);

    opacity: 1;
}


/* =========================================================
   11. SMALL PREMIUM GLOW BEHIND IMAGE
   ========================================================= */

selector .elementor-element-5cfbc7a::after {
    content: "";

    position: absolute;

    width: 180px;
    height: 180px;

    right: -50px;
    bottom: -50px;

    background:
        radial-gradient(
            circle,
            rgba(255, 206, 58, 0.16),
            transparent 68%
        );

    filter: blur(25px);

    pointer-events: none;

    z-index: -1;
}


/* =========================================================
   12. TABLET
   ========================================================= */

@media (max-width: 1024px) {

    selector {
        border-radius: 0 0 26px 26px;
    }

    selector .elementor-element-993c01d p {
        font-size: clamp(30px, 5vw, 40px);
    }

    selector .elementor-element-e48adae p {
        font-size: 15px;
    }

    selector .elementor-element-fcd108f img {
        transform: rotate(1.5deg);
    }

    selector .elementor-element-5cfbc7a::before {
        inset: -5px;
    }
}


/* =========================================================
   13. MOBILE
   ========================================================= */

@media (max-width: 767px) {

    selector {
        border-radius: 0 0 22px 22px;

        overflow: hidden;
    }

    selector::before {
        width: 260px;
        height: 260px;

        top: -150px;
        right: -100px;

        filter: blur(65px);
    }

    selector::after {
        width: 240px;
        height: 240px;

        bottom: -150px;
        left: -100px;

        filter: blur(65px);
    }


    /* Text */

    selector .elementor-element-ffed1b2 {
        text-align: center;
    }

    selector .elementor-element-993c01d p {
        font-size: clamp(28px, 8vw, 34px);
        line-height: 1.45;
        letter-spacing: 0;
    }


    /* Gold line */

    selector .elementor-element-993c01d::after {
        width: 50px;

        margin-top: 11px;
        margin-left: auto;
        margin-right: auto;
    }


    /* Description */

    selector .elementor-element-e48adae p {
        max-width: 340px;

        margin-left: auto;
        margin-right: auto;

        font-size: 14px;
        line-height: 2;
    }


    /* Image */

    selector .elementor-element-fcd108f img {
        transform: none;

        border-radius: 16px;

        box-shadow:
            0 18px 40px rgba(0, 0, 0, 0.25);
    }

    selector .elementor-element-5cfbc7a::before {
        inset: -4px;

        border-radius: 20px;
    }

    selector .elementor-element-5cfbc7a::after {
        display: none;
    }

    selector .elementor-element-5cfbc7a:hover img {
        transform: translateY(-4px);
    }
}


/* =========================================================
   14. REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

    selector *,
    selector *::before,
    selector *::after {
        transition: none !important;
        animation: none !important;
    }

    selector .elementor-element-fcd108f img {
        transform: none !important;
    }
}

/* حذف کامل بکگراند عکس */
.elementor-widget-image,
.elementor-widget-image .elementor-widget-container,
.elementor-widget-image img {
    background: transparent !important;
    background-color: transparent !important;
}

/* اطمینان از شفاف بودن خود تصویر */
.elementor-widget-image img {
    mix-blend-mode: normal !important;
}

/* =========================================
   RAMIS - Product Category Cards
   ========================================= */

.products.elementor-grid {
    gap: 24px !important;
}

.products.elementor-grid .product-category {
    position: relative;
    overflow: hidden;
    margin: 0 !important;
    padding: 14px !important;
    background: #ffffff;
    border: 1px solid rgba(0, 102, 96, 0.10);
    border-radius: 24px;
    box-shadow: 0 8px 30px rgba(0, 60, 56, 0.06);
    transition:
        transform .4s cubic-bezier(.2,.8,.2,1),
        box-shadow .4s ease,
        border-color .4s ease;
}

/* لینک کامل کارت */
.products.elementor-grid .product-category > a {
    position: relative;
    display: block;
    text-decoration: none !important;
    color: inherit !important;
    overflow: hidden;
    border-radius: 17px;
}

/* =========================================
   Image
   ========================================= */

.products.elementor-grid .product-category img {
    display: block;
    width: 100%;
    aspect-ratio: 1 / 1;
    object-fit: cover;
    border-radius: 18px;
    transition:
        transform .6s cubic-bezier(.2,.8,.2,1),
        filter .4s ease;
}

/* لایه گرادینت روی عکس */
.products.elementor-grid .product-category > a::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: 18px;
    background:
        linear-gradient(
            180deg,
            transparent 50%,
            rgba(0, 102, 96, 0.72) 100%
        );
    opacity: 0;
    pointer-events: none;
    transition: opacity .4s ease;
}

/* =========================================
   Title
   ========================================= */

.products.elementor-grid
.product-category
.woocommerce-loop-category__title {
    position: relative;
    z-index: 2;

    display: flex;
    align-items: center;
    justify-content: space-between;

    margin: 14px 4px 3px !important;
    padding: 0 !important;

    font-size: 17px !important;
    font-weight: 700 !important;
    line-height: 1.8 !important;

    color: #123c39 !important;
    text-align: right;

    transition: color .35s ease;
}

/* =========================================
   Count
   ========================================= */

.products.elementor-grid
.product-category
.woocommerce-loop-category__title
.count {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    min-width: 30px;
    height: 30px;
    padding: 0 8px;

    margin-right: 8px;

    border-radius: 10px;

    background: rgba(0, 102, 96, 0.08);
    color: #006660;

    font-size: 12px !important;
    font-weight: 700;

    transition:
        background .35s ease,
        color .35s ease,
        transform .35s ease;
}

/* =========================================
   Hover
   ========================================= */

.products.elementor-grid
.product-category:hover {
    transform: translateY(-8px);

    border-color: rgba(0, 102, 96, 0.28);

    box-shadow:
        0 18px 45px rgba(0, 102, 96, 0.14),
        0 5px 15px rgba(0, 0, 0, 0.04);
}

.products.elementor-grid
.product-category:hover img {
    transform: scale(1.055);
    filter: saturate(1.08);
}

.products.elementor-grid
.product-category:hover > a::after {
    opacity: 1;
}

.products.elementor-grid
.product-category:hover
.woocommerce-loop-category__title {
    color: #006660 !important;
}

.products.elementor-grid
.product-category:hover
.woocommerce-loop-category__title
.count {
    background: #006660;
    color: #ffffff;
    transform: translateY(-2px);
}

/* =========================================
   خط طلایی بالای کارت هنگام Hover
   ========================================= */

.products.elementor-grid
.product-category::before {
    content: "";
    position: absolute;

    top: 0;
    left: 50%;

    width: 0;
    height: 3px;

    background: #f5b51b;
    border-radius: 0 0 10px 10px;

    transform: translateX(-50%);
    transition: width .4s cubic-bezier(.2,.8,.2,1);

    z-index: 5;
}

.products.elementor-grid
.product-category:hover::before {
    width: 55%;
}

/* =========================================
   Mobile
   ========================================= */

@media (max-width: 767px) {

    .products.elementor-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
        gap: 14px !important;
    }

    .products.elementor-grid .product-category {
        padding: 9px !important;
        border-radius: 18px;
    }

    .products.elementor-grid .product-category > a {
        border-radius: 13px;
    }

    .products.elementor-grid .product-category img {
        border-radius: 13px;
    }

    .products.elementor-grid
    .product-category
    .woocommerce-loop-category__title {
        margin: 10px 2px 2px !important;
        font-size: 14px !important;
        line-height: 1.7 !important;
    }

    .products.elementor-grid
    .product-category
    .woocommerce-loop-category__title
    .count {
        min-width: 25px;
        height: 25px;
        padding: 0 6px;
        margin-right: 5px;
        font-size: 10px !important;
        border-radius: 8px;
    }

    /* موبایل حرکت کارت کمتر باشد */
    .products.elementor-grid
    .product-category:hover {
        transform: translateY(-4px);
    }
}

@media (min-width: 768px) and (max-width: 1024px) {

    ul.products.elementor-grid {
        display: grid !important;
        grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
        grid-auto-flow: row !important;
        gap: 12px !important;
    }

    ul.products.elementor-grid > li.product-category {
        grid-column: auto !important;
        grid-row: auto !important;
        width: 100% !important;
        max-width: none !important;
        flex: none !important;
        margin: 0 !important;
        padding: 7px !important;
    }

    ul.products.elementor-grid > li.product-category img {
        width: 100% !important;
        aspect-ratio: 1 / 1 !important;
        object-fit: cover !important;
    }
}

/* =========================================================
   RAMIS SHOP ARCHIVE
   Brand Color: #006660
   Secondary: #004F4B
========================================================= */


/* =========================================================
   1. SHOP ARCHIVE BASE
========================================================= */

.woocommerce.columns-4 {
    --ramis-primary: #006660;
    --ramis-primary-dark: #004f4b;
    --ramis-text: #202525;
    --ramis-muted: #777;
    --ramis-border: rgba(0, 102, 96, 0.10);
    --ramis-bg: #f8faf9;
}


/* =========================================================
   2. ADVANCED FILTER BOX
========================================================= */

.pooshe-advanced-filters {
    position: relative;

    margin-bottom: 28px;
    padding: 18px 20px;

    background: #ffffff;

    border: 1px solid var(--ramis-border);
    border-radius: 20px;

    box-shadow:
        0 8px 30px rgba(0, 0, 0, 0.035),
        0 2px 8px rgba(0, 102, 96, 0.025);
}


/* =========================================================
   FILTER HEADER
========================================================= */

.pooshe-advanced-filters .filters-header {
    display: flex;
    align-items: center;
    justify-content: space-between;

    margin-bottom: 15px;
    padding-bottom: 14px;

    border-bottom: 1px solid rgba(0, 102, 96, 0.07);
}


/* عنوان فیلتر */

.pooshe-advanced-filters .filters-title {
    display: flex;
    align-items: center;
    gap: 9px;

    color: var(--ramis-text);

    font-size: 15px;
    font-weight: 800;
}


/* آیکون عنوان */

.pooshe-advanced-filters .filters-title i {
    width: 34px;
    height: 34px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    background: rgba(0, 102, 96, 0.08);

    color: var(--ramis-primary);

    border-radius: 10px;

    font-size: 14px;
}


/* =========================================================
   FILTER ROW
========================================================= */

.pooshe-advanced-filters .filter-row {
    display: grid;

    grid-template-columns:
        minmax(190px, 1.5fr)
        minmax(220px, 1.3fr)
        minmax(190px, 1.2fr)
        auto;

    gap: 12px;

    align-items: center;
}


/* =========================================================
   FILTER INPUTS
========================================================= */

.pooshe-advanced-filters select,
.pooshe-advanced-filters input {
    width: 100%;

    height: 48px;

    padding: 0 15px;

    background: #fafcfc;

    color: #333;

    border: 1px solid rgba(0, 102, 96, 0.10);
    border-radius: 12px;

    outline: none;

    font-family: inherit;
    font-size: 13px;

    transition:
        border-color .25s ease,
        background .25s ease,
        box-shadow .25s ease;
}


/* Hover */

.pooshe-advanced-filters select:hover,
.pooshe-advanced-filters input:hover {
    border-color: rgba(0, 102, 96, 0.22);
}


/* Focus */

.pooshe-advanced-filters select:focus,
.pooshe-advanced-filters input:focus {
    background: #ffffff;

    border-color: var(--ramis-primary);

    box-shadow:
        0 0 0 4px rgba(0, 102, 96, 0.07);
}


/* =========================================================
   PRICE RANGE
========================================================= */

.pooshe-advanced-filters .filter-price {
    display: flex;
    align-items: center;
    gap: 8px;
}

.pooshe-advanced-filters .filter-price input {
    min-width: 0;
}

.pooshe-advanced-filters .price-sep {
    color: #aaa;
    font-weight: 600;
}


/* =========================================================
   FILTER SUBMIT BUTTON
========================================================= */

.pooshe-advanced-filters .filter-submit .btn {
    height: 48px;

    min-width: 100px;

    padding: 0 20px;

    background: var(--ramis-primary) !important;

    color: #ffffff !important;

    border: 1px solid var(--ramis-primary) !important;
    border-radius: 12px;

    font-family: inherit;
    font-size: 13px;
    font-weight: 700;

    box-shadow:
        0 6px 16px rgba(0, 102, 96, 0.14);

    transition:
        background .3s ease,
        transform .3s ease,
        box-shadow .3s ease;
}


.pooshe-advanced-filters .filter-submit .btn:hover {
    background: var(--ramis-primary-dark) !important;

    transform: translateY(-2px);

    box-shadow:
        0 10px 22px rgba(0, 102, 96, 0.20);
}


/* =========================================================
   3. ACTIVE FILTERS
========================================================= */

.pooshe-advanced-filters .filter-active {
    display: flex;
    flex-wrap: wrap;
    align-items: center;

    gap: 8px;

    margin-top: 14px;
    padding-top: 14px;

    border-top: 1px solid rgba(0, 102, 96, 0.07);
}


/* Active tag */

.pooshe-advanced-filters .filter-tag {
    display: inline-flex;
    align-items: center;
    gap: 7px;

    min-height: 34px;

    padding: 5px 11px;

    background: rgba(0, 102, 96, 0.07);

    color: var(--ramis-primary);

    border: 1px solid rgba(0, 102, 96, 0.10);
    border-radius: 9px;

    font-size: 12px;
    font-weight: 700;

    transition: all .25s ease;
}


.pooshe-advanced-filters .filter-tag:hover {
    background: var(--ramis-primary);
    color: #ffffff;
}


/* Clear all */

.pooshe-advanced-filters .filter-tag.tag-clear {
    background: transparent;

    color: #888;

    border-color: rgba(0,0,0,.08);
}

.pooshe-advanced-filters .filter-tag.tag-clear:hover {
    background: #f5f5f5;
    color: #555;
}


/* =========================================================
   4. RESULT COUNT
========================================================= */

.woocommerce-result-count {
    margin: 0 0 18px 0 !important;

    color: #777 !important;

    font-size: 13px !important;
    font-weight: 500;

    line-height: 1.8;
}


/* عدد نتایج */

.woocommerce-result-count::before {
    content: "محصولات ";

    color: var(--ramis-primary);

    font-weight: 800;
}


/* =========================================================
   5. HIDE OLD WOOCOMMERCE SORT
========================================================= */

.woocommerce-ordering {
    display: none !important;
}


/* =========================================================
   6. PRODUCT GRID
   فقط نظم و فاصله؛ ظاهر کارت‌ها دست نخورده
========================================================= */

ul.products.elementor-grid {
    gap: 24px !important;

    margin-top: 0 !important;
}


/* =========================================================
   7. PRODUCT CARD
   تغییرات خیلی محدود
========================================================= */

ul.products .product-card {
    border-radius: 20px;

    transition:
        transform .35s ease,
        box-shadow .35s ease,
        border-color .35s ease;
}


/* فقط Hover ظریف */

ul.products .product-card:hover {
    transform: translateY(-5px);

    box-shadow:
        0 16px 35px rgba(0, 102, 96, 0.08);
}


/* =========================================================
   8. PRODUCT IMAGE
   ساختار خود قالب حفظ می‌شود
========================================================= */

ul.products .product-card .thumbnail {
    overflow: hidden;

    border-radius: 17px;
}


/* Zoom بسیار ملایم */

ul.products .product-card .thumbnail img {
    transition:
        transform .55s cubic-bezier(.2,.8,.2,1);
}

ul.products .product-card:hover .thumbnail img {
    transform: scale(1.035);
}


/* =========================================================
   9. PRODUCT TITLE
========================================================= */

ul.products .product-card
.woocommerce-loop-product__title {
    transition: color .25s ease;
}

ul.products .product-card:hover
.woocommerce-loop-product__title {
    color: var(--ramis-primary);
}


/* =========================================================
   10. PRODUCT CATEGORY
========================================================= */

ul.products .product-card .posted_in a {
    color: #858585;

    transition: color .25s ease;
}

ul.products .product-card .posted_in a:hover {
    color: var(--ramis-primary);
}


/* =========================================================
   11. PRICE
========================================================= */

ul.products .product-card .prices ins {
    color: var(--ramis-primary);
}

ul.products .product-card .prices del {
    color: #aaa;
}


/* =========================================================
   12. SALE BADGE
========================================================= */

ul.products .product-card .onsale {
    background: var(--ramis-primary) !important;

    color: #ffffff !important;

    border-radius: 9px !important;

    font-size: 11px;

    font-weight: 700;

    box-shadow:
        0 5px 14px rgba(0, 102, 96, 0.18);
}


/* =========================================================
   13. UPDATED BADGE
========================================================= */

ul.products .product-card
.pooshe-badge--updated {
    background: rgba(0, 102, 96, 0.92);

    color: #ffffff;

    border-radius: 8px;

    font-size: 10px;
    font-weight: 700;

    box-shadow:
        0 5px 14px rgba(0, 102, 96, 0.15);
}


/* =========================================================
   14. FAVORITE BUTTON
   فقط هماهنگ کردن رنگ
========================================================= */

ul.products .product-card .add-product-favo {
    transition:
        background .25s ease,
        color .25s ease,
        transform .25s ease;
}

ul.products .product-card .add-product-favo:hover {
